content.text:
        uint64_t want = (static_cast<uint64_t>(d_.cells[s]) + 1) / 2;
        if (d_.banks[s].size() != want) return false;
        if (d_.cells[s] > 2u * 65536u) return false;
        rows += want;
    }
    if (rows > 65536) return false;
    if (d_.bitmaps.size() > 8193 || d_.nexthops.size() > 8192) return false;
    for (size_t i = 0; i < d_.bitmaps.size(); ++i) {
        if (i > 0 && !(d_.bitmaps[i] > d_.bitmaps[i - 1])) return false;  // distinct, increasing
    }
    return true;
}

bool mark(uint32_t stage, uint32_t cell, uint32_t count) {
    if (count > d_.cells[stage] - cell) return false;
    for (uint32_t c = cell; c < cell + count; ++c) {
        if (used_[stage][c]) return false;   // charged slots never overlap
        used_[stage][c] = 1;
    }
    return true;
}

bool visit(uint32_t stage, uint32_t cell, bool as_bulk, uint32_t origin,
           uint32_t depth, uint64_t rhi, uint64_t rlo, uint32_t& idx_out) {
    if (stage >= RAM_NUM) return false;
    if (cell >= d_.cells[stage]) return false;
    if (as_bulk && (cell & 1u)) return false;  // bulk slots are two cells at even offsets
    const std::bitset<256>& w = d_.banks[stage][cell / 2];
    uint32_t off = (cell & 1u) ? 128 : 0;
    int type = static_cast<int>(rec_get(w, static_cast<int>(off), 3));
    if (type < 1 || type > 5) return false;
    if (!image_is_half(type) && (cell & 1u)) return false;
    if (as_bulk && image_is_half(type) && !rec_clear(w, 128, 128)) return false;  // zero padded upper half

    nodes_.push_back(VNode());
    uint32_t idx = static_cast<uint32_t>(nodes_.size() - 1);
    VNode& n = nodes_[idx];
    n.stage = stage;
    n.cell = cell;
    n.type = type;
    n.depth = depth;
    n.origin = origin;
    n.rhi = rhi;
    n.rlo = rlo;
    n.bmp = static_cast<uint32_t>(rec_get(w, static_cast<int>(off) + OFF_BMP, OFF_BMP_W));
    uint32_t charge = as_bulk ? 2u : static_cast<uint32_t>(image_cell_size(type));
    if (charge == 2u && (cell & 1u)) return false;
    if (!mark(stage, cell, charge)) return false;

    bool ok = true;
    if (type == 4 || type == 5) {
        ok = decode_inline(w, static_cast<int>(off), n);
    } else {
        ok = decode_ni(w, static_cast<int>(off), n);
        if (ok) {
            if (type == 3) {
                ok = decode_children(w, static_cast<int>(off) + OFF_DIRECT3, n, 3) &&
                     decode_type3(w, static_cast<int>(off), n);
            } else {
                ok = decode_children(w, static_cast<int>(off) + OFF_CHILD, n, type == 1 ? 2 : 6);
            }
        }
    }
    // Reserved bits of every record layout must be zero.
    if (ok) {
        int rsv_off = 0, rsv_w = 0;
        switch (type) {
            case 1: rsv_off = 127; rsv_w = 1; break;
            case 2: rsv_off = 255; rsv_w = 1; break;
            case 3: rsv_off = 249; rsv_w = 7; break;
            case 4: rsv_off = 119; rsv_w = 9; break;
            default: rsv_off = 213; rsv_w = 43; break;
        }
        ok = rec_clear(w, static_cast<int>(off) + rsv_off, rsv_w);
    }
    if (!ok) return false;

    // Own prefixes: bounds, ownership and region membership.
    uint32_t omin = owner_min_len(origin), omax = owner_max_len(origin);
    for (size_t i = 0; i < n.own.size(); ++i) {
        const FibPfx& p = n.own[i];
        if (p.len < omin || p.len > omax) return false;
        if (p.len < depth) return false;
        if (type != 4 && type != 5 && p.len > depth + 5) return false;
        if (!region_match(p.hi, p.lo, rhi, rlo, depth)) return false;
        prefixes_.push_back(p);
        // More entries than the FIB bound can never become a valid image.
        if (prefixes_.size() > static_cast<size_t>(FIB_MAX_PREFIXES) + 64u) return false;
    }

    // Children, strictly lower stages, six bits deeper.  Copies are taken
    // because the recursion below grows nodes_ and would invalidate 'n'.
    if (!nodes_[idx].edges.empty() && depth + 6 > omax) return false;
    std::vector<VEdge> edges = nodes_[idx].edges;
    uint32_t prev_key = 0;
    bool first_edge = true;
    uint32_t total = static_cast<uint32_t>(nodes_[idx].own.size());
    for (size_t i = 0; i < edges.size(); ++i) {
        const VEdge& e = edges[i];
        if (!first_edge && e.key <= prev_key) return false;
        first_edge = false;
        prev_key = e.key;
        if (e.stage >= stage) return false;  // strictly lower than the parent
        uint64_t chi = rhi, clo = rlo;
        fib_set_bits(chi, clo, depth, 6, e.key);
        uint32_t cidx;
        if (!visit(e.stage, e.cell, e.bulk_child, origin, depth + 6, chi, clo, cidx)) return false;
        total += nodes_[cidx].size;
    }
    nodes_[idx].size = total;
    if (type == 4 && total != 1) return false;
    if (type == 5 && total != 2) return false;
    if (type != 4 && type != 5 && total < 3) return false;
    if (type == 3 && (edges.size() < 7 || edges.size() > 64)) return false;
    idx_out = idx;
    return true;
}

bool decode_inline(const std::bitset<256>& w, int off, VNode& n) {
    int count = (n.type == 5) ? 2 : 1;
    int p = off + OFF_INLINE;
    uint64_t seen_len[2] = {0, 0};
    uint64_t seen_hi[2] = {0, 0}, seen_lo[2] = {0, 0};
    for (int i = 0; i < count; ++i) {
        uint64_t frag = rec_get(w, p, OFF_FRAG_W); p += OFF_FRAG_W;
        uint64_t rel = rec_get(w, p, OFF_LEN_W); p += OFF_LEN_W;
        uint64_t hop = rec_get(w, p, OFF_HOP_W); p += OFF_HOP_W;
        if (hop > HOP_MAX_VALUE) return false;
        if (rel > 64) return false;
        if (rel == 0) {
            if (frag != 0) return false;             // all-zero fragment for a /0 prefix
        } else if (rel < 64 && (frag & ((1ULL << (64 - rel)) - 1ULL)) != 0) {
            return false;                            // fragment host bits must be cleared
        }
        uint64_t len = n.origin + rel;
        if (len > 128) return false;
        uint64_t hi = n.rhi, lo = n.rlo;
        // The region above the node depth is not carried; rebuild it from the fragment.
        hi &= fib_mask_high(hi, n.depth < 64 ? n.depth : 64);
        lo = (n.depth <= 64) ? 0 : fib_mask_high(lo, n.depth - 64);
        if (n.origin == 0) { hi = frag; lo = 0; }
        else if (n.origin == 16) { hi = (n.rhi & (0xFFFFULL << 48)) | (frag >> 16); lo = 0; }
        else { hi = n.rhi; lo = frag; }
        if (i == 0) { seen_hi[i] = hi; seen_lo[i] = lo; seen_len[i] = len; }
        else {
            if (seen_hi[0] == hi && seen_lo[0] == lo && seen_len[0] == len) return false;  // distinct prefixes
        }
        FibPfx pf;
        pf.hi = hi; pf.lo = lo; pf.len = static_cast<uint32_t>(len); pf.hop = static_cast<uint32_t>(hop);
        n.own.push_back(pf);
    }
    return true;
}

bool decode_ni(const std::bitset<256>& w, int off, VNode& n) {
    uint64_t bid = rec_get(w, off + OFF_BITMAP_ID, OFF_BITMAP_ID_W);
    uint64_t base = rec_get(w, off + OFF_NI_BASE, OFF_NI_BASE_W);
    if (bid >= d_.bitmaps.size()) return false;
    uint64_t pattern = d_.bitmaps[bid];
    if (pattern & 1ULL) return false;  // bit0 is unused
    n.bitmap_id = static_cast<uint32_t>(bid);
    n.ni_base = static_cast<uint32_t>(base);
    n.ni_len = static_cast<uint32_t>(__builtin_popcountll(pattern));
    if (n.ni_len == 0) {
        if (n.ni_base != 0) return false;
    } else {
        if (static_cast<uint64_t>(n.ni_base) + n.ni_len > d_.nexthops.size()) return false;
    }
    uint32_t slot = 0;
    for (uint32_t pos = 1; pos < 64; ++pos) {
        if (!(pattern & (1ULL << pos))) continue;
        uint32_t l = 0;
        while ((1u << (l + 1)) <= pos) ++l;
        uint32_t v = pos - (1u << l);
        if (l > 5) return false;
        uint32_t len = n.depth + l;
        if (len > 128) return false;
        uint64_t hi = n.rhi, lo = n.rlo;
        fib_set_bits(hi, lo, n.depth, l, v);
        FibPfx p;
        p.hi = hi; p.lo = lo; p.len = len; p.hop = d_.nexthops[n.ni_base + slot];
        if (p.hop > HOP_MAX_VALUE) return false;
        n.own.push_back(p);
        ++slot;
    }
    if (slot != n.ni_len) return false;
    return true;
}

bool decode_children(const std::bitset<256>& w, int p, VNode& n, int slots) {
    bool absent_seen = false;
